ALTER TABLE public.vault_cards ALTER COLUMN visibility SET DEFAULT 'inherit';
ALTER TABLE public.posts ADD COLUMN collectible_id uuid REFERENCES public.vault_cards(id) ON DELETE RESTRICT;
ALTER TABLE public.posts ADD COLUMN shared_post_id uuid REFERENCES public.posts(id) ON DELETE RESTRICT;
CREATE INDEX posts_collectible_privacy_idx ON public.posts(collectible_id);
CREATE INDEX posts_shared_privacy_idx ON public.posts(shared_post_id);
CREATE OR REPLACE FUNCTION public.social_users_unblocked(_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(_owner=auth.uid(),false) OR NOT EXISTS(SELECT 1 FROM public.user_blocks b WHERE (b.blocker_id=_owner AND b.blocked_id=auth.uid()) OR (b.blocker_id=auth.uid() AND b.blocked_id=_owner)) $$;
CREATE OR REPLACE FUNCTION public.social_audience_visible(_owner uuid,_audience text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(_owner=auth.uid(),false) OR (public.social_users_unblocked(_owner) AND CASE _audience WHEN 'public' THEN true WHEN 'followers' THEN EXISTS(SELECT 1 FROM public.follows WHERE follower_id=auth.uid() AND followee_id=_owner) WHEN 'friends' THEN EXISTS(SELECT 1 FROM public.story_close_friends WHERE owner_id=_owner AND friend_id=auth.uid()) WHEN 'close_friends' THEN EXISTS(SELECT 1 FROM public.story_close_friends WHERE owner_id=_owner AND friend_id=auth.uid()) ELSE false END) $$;
CREATE FUNCTION public.social_vault_card_visible(_card uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.vault_cards c WHERE c.id=_card AND (c.user_id=auth.uid() OR (public.social_users_unblocked(c.user_id) AND EXISTS(SELECT 1 FROM public.vault_settings s WHERE s.user_id=c.user_id AND public.social_audience_visible(c.user_id,s.visibility)) AND (c.visibility='inherit' OR public.social_audience_visible(c.user_id,c.visibility))))) $$;
REVOKE ALL ON FUNCTION public.social_vault_card_visible(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.social_vault_card_visible(uuid) TO anon,authenticated,service_role;
CREATE FUNCTION public.social_post_chain_visible(_post uuid,_visited uuid[] DEFAULT '{}'::uuid[]) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; BEGIN IF _post=ANY(_visited) OR cardinality(_visited)>=16 THEN RETURN false; END IF; SELECT * INTO p FROM public.posts WHERE id=_post; IF NOT FOUND THEN RETURN false; END IF; IF p.user_id=auth.uid() THEN RETURN true; END IF; RETURN p.moderation_status='approved' AND public.social_audience_visible(p.user_id,p.visibility) AND (p.collectible_id IS NULL OR public.social_vault_card_visible(p.collectible_id)) AND (p.shared_post_id IS NULL OR public.social_post_chain_visible(p.shared_post_id,array_append(_visited,_post))); END $$;
REVOKE ALL ON FUNCTION public.social_post_chain_visible(uuid,uuid[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.social_post_chain_visible(uuid,uuid[]) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.social_post_visible(_post uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.social_post_chain_visible(_post) $$;
CREATE OR REPLACE FUNCTION public.social_post_interactable(_post uuid,_comment boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.social_post_visible(_post) AND EXISTS(SELECT 1 FROM public.posts WHERE id=_post AND moderation_status='approved' AND (NOT _comment OR allow_comments)) $$;
DROP POLICY "Vault per-card privacy restriction" ON public.vault_cards;
CREATE POLICY "Vault per-card privacy restriction" ON public.vault_cards AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(public.social_vault_card_visible(id));
CREATE OR REPLACE FUNCTION public.can_view_vault_owner(_owner uuid,_viewer uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _viewer IS NOT DISTINCT FROM auth.uid() AND (COALESCE(_owner=auth.uid(),false) OR EXISTS(SELECT 1 FROM public.vault_settings WHERE user_id=_owner AND public.social_audience_visible(_owner,visibility))) $$;
GRANT SELECT ON public.vault_cards,public.posts,public.post_comments,public.post_reactions TO anon;
GRANT EXECUTE ON FUNCTION public.can_view_vault_owner(uuid,uuid) TO anon,authenticated;
DROP POLICY "Owner deletes comment" ON public.post_comments;
CREATE POLICY "Authorized users delete own comments" ON public.post_comments FOR DELETE TO authenticated USING(user_id=auth.uid() AND public.social_post_visible(post_id));
CREATE POLICY "Authorized users edit own comments" ON public.post_comments FOR UPDATE TO authenticated USING(user_id=auth.uid() AND public.social_post_interactable(post_id,true)) WITH CHECK(user_id=auth.uid() AND public.social_post_interactable(post_id,true));
DROP POLICY "Users delete own reaction" ON public.post_reactions;
CREATE POLICY "Authorized users delete own reactions" ON public.post_reactions FOR DELETE TO authenticated USING(user_id=auth.uid() AND public.social_post_visible(post_id));
CREATE OR REPLACE FUNCTION public.guard_social_post_moderation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('anon','authenticated') THEN IF NEW.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Post owner mismatch'; END IF; IF TG_OP='UPDATE' AND (NEW.moderation_status IS DISTINCT FROM OLD.moderation_status OR NEW.moderation_reason IS DISTINCT FROM OLD.moderation_reason) THEN RAISE EXCEPTION 'Moderation fields require authorized review'; END IF; IF TG_OP='INSERT' AND (NEW.moderation_status IS DISTINCT FROM 'approved' OR NEW.moderation_reason IS NOT NULL) THEN RAISE EXCEPTION 'Moderation fields require authorized review'; END IF; IF NEW.collectible_id IS NOT NULL AND NOT public.social_vault_card_visible(NEW.collectible_id) THEN RAISE EXCEPTION 'Collectible unavailable'; END IF; IF NEW.shared_post_id IS NOT NULL AND (NEW.shared_post_id=NEW.id OR NOT public.social_post_visible(NEW.shared_post_id)) THEN RAISE EXCEPTION 'Shared post unavailable'; END IF; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.guard_social_child_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.post_id IS DISTINCT FROM OLD.post_id OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Interaction identity is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER social_comment_identity BEFORE UPDATE ON public.post_comments FOR EACH ROW EXECUTE FUNCTION public.guard_social_child_identity();
CREATE TRIGGER social_reaction_identity BEFORE UPDATE ON public.post_reactions FOR EACH ROW EXECUTE FUNCTION public.guard_social_child_identity();
COMMENT ON FUNCTION public.social_vault_card_visible(uuid) IS 'DRAFT ONLY, separate production approval required: collection audience caps card audience; inherit uses collection; existing private cards unchanged.';